// ===== Render functions for Amazon Customers (New/Lost) tab =====
var _amzCustState = {
  channel: 'all',
  month: 0,
  tableType: 'new',
  search: '',
  province: '',
  page: 1,
  perPage: 20,
  chart: null,
  sortKey: 't',
  sortDir: 'desc'
};

function _amzCustFmt(n) {
  if (n == null) return '0';
  return n.toLocaleString('th-TH');
}

function _amzCustFmtBaht(n) {
  if (n == null) return '฿0.00';
  return '฿' + n.toLocaleString('th-TH', {minimumFractionDigits:2, maximumFractionDigits:2});
}

function _amzCustGetData() {
  var D = AMZ_CUST_DATA;
  var ch = _amzCustState.channel;
  var rows = [];
  if (ch === 'all' || ch === 'amazon') rows = rows.concat(D.AMZ);
  if (ch === 'all' || ch === 'souvenir') rows = rows.concat(D.SOV);
  return rows.filter(function(r){ return r.c !== 'Grand Total'; });
}

function _amzCustGetSummary() {
  var D = AMZ_CUST_DATA;
  var ch = _amzCustState.channel;
  var months = D.MONTHS;
  var result = [];
  for (var i = 0; i < months.length; i++) {
    var n = 0, l = 0;
    if (ch === 'all' || ch === 'amazon') {
      n += D.SUMMARY.amazon[i].n;
      l += D.SUMMARY.amazon[i].l;
    }
    if (ch === 'all' || ch === 'souvenir') {
      n += D.SUMMARY.souvenir[i].n;
      l += D.SUMMARY.souvenir[i].l;
    }
    result.push({m: i+1, n: n, l: l, net: n - l});
  }
  var totN = 0, totL = 0;
  if (ch === 'all' || ch === 'amazon') {
    totN += D.SUMMARY.amzTotal.n;
    totL += D.SUMMARY.amzTotal.l;
  }
  if (ch === 'all' || ch === 'souvenir') {
    totN += D.SUMMARY.sovTotal.n;
    totL += D.SUMMARY.sovTotal.l;
  }
  return {months: result, totalNew: totN, totalLost: totL, totalNet: totN - totL};
}

function _amzCustFilteredRows() {
  var allRows = _amzCustGetData();
  var st = _amzCustState;
  var type = st.tableType;
  var month = st.month;
  var search = st.search.toLowerCase();
  var prov = st.province;

  var filtered = [];
  for (var i = 0; i < allRows.length; i++) {
    var r = allRows[i];
    if (type === 'new' && !r.nf) continue;
    if (type === 'lost' && !r.lf) continue;
    if (month > 0) {
      var flag = type === 'new' ? r.nf : r.lf;
      if (flag.indexOf('เดือน ' + month) === -1) continue;
    }
    if (prov && r.p !== prov) continue;
    if (search) {
      var hay = (r.c + ' ' + r.n + ' ' + r.p + ' ' + r.d).toLowerCase();
      if (hay.indexOf(search) === -1) continue;
    }
    filtered.push(r);
  }

  var key = st.sortKey;
  var dir = st.sortDir === 'asc' ? 1 : -1;
  filtered.sort(function(a, b) {
    var va, vb;
    if (key === 'f') {
      va = type === 'new' ? a.nf : a.lf;
      vb = type === 'new' ? b.nf : b.lf;
    } else {
      va = a[key]; vb = b[key];
    }
    if (typeof va === 'string') return va.localeCompare(vb, 'th') * dir;
    return ((va || 0) - (vb || 0)) * dir;
  });

  return filtered;
}

function amzCustSort(key) {
  var st = _amzCustState;
  if (st.sortKey === key) {
    st.sortDir = st.sortDir === 'asc' ? 'desc' : 'asc';
  } else {
    st.sortKey = key;
    st.sortDir = key === 't' ? 'desc' : 'asc';
  }
  st.page = 1;
  _amzCustRenderTable();
}

function amzCustFilterChannel(ch) {
  _amzCustState.channel = ch;
  _amzCustState.page = 1;
  _amzCustState.province = '';
  var sel = document.getElementById('amzCustProvSel');
  if (sel) sel.value = '';
  _amzCustRenderKPI();
  _amzCustRenderChart();
  _amzCustRenderPills();
  _amzCustPopulateProvinces();
  _amzCustRenderTable();
}

function amzCustFilterMonth(m) {
  _amzCustState.month = m;
  _amzCustState.page = 1;
  _amzCustRenderPills();
  _amzCustRenderTable();
}

function amzCustSwitchTable(type) {
  _amzCustState.tableType = type;
  _amzCustState.page = 1;
  _amzCustState.sortKey = 't';
  _amzCustState.sortDir = 'desc';
  var btns = document.querySelectorAll('.amz-cust-tab-btn');
  for (var i = 0; i < btns.length; i++) btns[i].classList.remove('active');
  if (type === 'new') btns[0].classList.add('active');
  else btns[1].classList.add('active');
  _amzCustRenderTable();
}

function amzCustSearch(q) {
  _amzCustState.search = q;
  _amzCustState.page = 1;
  _amzCustRenderTable();
}

function amzCustFilterProvince(p) {
  _amzCustState.province = p;
  _amzCustState.page = 1;
  _amzCustRenderTable();
}

function amzCustSetPage(p) {
  _amzCustState.page = p;
  _amzCustRenderTable();
}

function _amzCustPopulateProvinces() {
  var rows = _amzCustGetData();
  var provSet = {};
  for (var i = 0; i < rows.length; i++) {
    if (rows[i].p) provSet[rows[i].p] = true;
  }
  var provs = Object.keys(provSet).sort(function(a,b){return a.localeCompare(b,'th')});
  var sel = document.getElementById('amzCustProvSel');
  if (!sel) return;
  var html = '<option value="">จังหวัดทั้งหมด</option>';
  for (var i = 0; i < provs.length; i++) {
    html += '<option value="' + provs[i] + '">' + provs[i] + '</option>';
  }
  sel.innerHTML = html;
}

function _amzCustRenderKPI() {
  var summary = _amzCustGetSummary();
  var allRows = _amzCustGetData();
  var total = allRows.length;
  var netVal = summary.totalNet;
  var netClass = netVal >= 0 ? 'ac-net-pos' : 'ac-net-neg';
  var netSign = netVal >= 0 ? '+' : '';
  var el = document.getElementById('amzCustKPI');
  if (!el) return;
  el.innerHTML =
    '<div class="ack-card ac-blue"><div class="ack-icon">👥</div><div class="ack-val">' + _amzCustFmt(total) + '</div><div class="ack-label">ลูกค้าทั้งหมด</div></div>' +
    '<div class="ack-card ac-green"><div class="ack-icon">🆕</div><div class="ack-val" style="color:#16a34a">' + _amzCustFmt(summary.totalNew) + '</div><div class="ack-label">ลูกค้าใหม่</div></div>' +
    '<div class="ack-card ac-red"><div class="ack-icon">📉</div><div class="ack-val" style="color:#dc2626">' + _amzCustFmt(summary.totalLost) + '</div><div class="ack-label">ลูกค้าหาย</div></div>' +
    '<div class="ack-card ' + netClass + '"><div class="ack-icon">📊</div><div class="ack-val" style="color:' + (netVal >= 0 ? '#16a34a' : '#dc2626') + '">' + netSign + _amzCustFmt(netVal) + '</div><div class="ack-label">เพิ่ม/ลดสุทธิ</div></div>';
}

function _amzCustRenderChart() {
  var summary = _amzCustGetSummary();
  var months = AMZ_CUST_DATA.MONTHS;
  var labels = [];
  var newData = [], lostData = [], netData = [];
  for (var i = 0; i < summary.months.length; i++) {
    labels.push(months[i]);
    newData.push(summary.months[i].n);
    lostData.push(-summary.months[i].l);
    netData.push(summary.months[i].net);
  }

  var canvas = document.getElementById('amzCustChart');
  if (!canvas) return;
  var ctx = canvas.getContext('2d');
  if (_amzCustState.chart) {
    _amzCustState.chart.destroy();
    _amzCustState.chart = null;
  }

  _amzCustState.chart = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: labels,
      datasets: [
        {
          label: 'ลูกค้าใหม่',
          data: newData,
          backgroundColor: 'rgba(22,163,74,0.7)',
          borderColor: '#16a34a',
          borderWidth: 1,
          borderRadius: 4,
          order: 2
        },
        {
          label: 'ลูกค้าหาย',
          data: lostData,
          backgroundColor: 'rgba(220,38,38,0.7)',
          borderColor: '#dc2626',
          borderWidth: 1,
          borderRadius: 4,
          order: 2
        },
        {
          label: 'สุทธิ',
          data: netData,
          type: 'line',
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37,99,235,0.1)',
          borderWidth: 2,
          pointRadius: 4,
          pointBackgroundColor: '#2563eb',
          fill: false,
          tension: 0.3,
          order: 1
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { position: 'top', labels: { font: {size:12}, usePointStyle: true, padding: 16 } },
        tooltip: {
          callbacks: {
            label: function(tipCtx) {
              var v = tipCtx.raw;
              return tipCtx.dataset.label + ': ' + (v < 0 ? '' : '+') + v.toLocaleString('th-TH') + ' ราย';
            }
          }
        }
      },
      scales: {
        x: { grid: { display: false } },
        y: {
          grid: { color: 'rgba(0,0,0,.06)' },
          ticks: {
            callback: function(v) { return v.toLocaleString('th-TH'); }
          }
        }
      }
    }
  });
}

function _amzCustRenderPills() {
  var el = document.getElementById('amzCustPills');
  if (!el) return;
  var months = AMZ_CUST_DATA.MONTHS;
  var cur = _amzCustState.month;
  var html = '<div class="amz-cust-pill' + (cur === 0 ? ' active' : '') + '" onclick="amzCustFilterMonth(0)">ทั้งหมด</div>';
  for (var i = 0; i < months.length; i++) {
    html += '<div class="amz-cust-pill' + (cur === i+1 ? ' active' : '') + '" onclick="amzCustFilterMonth(' + (i+1) + ')">' + months[i] + '</div>';
  }
  el.innerHTML = html;
}

function _amzCustRenderTable() {
  var rows = _amzCustFilteredRows();
  var st = _amzCustState;
  var total = rows.length;
  var pages = Math.ceil(total / st.perPage) || 1;
  if (st.page > pages) st.page = pages;
  var start = (st.page - 1) * st.perPage;
  var end = Math.min(start + st.perPage, total);
  var pageRows = rows.slice(start, end);

  // update sort indicators
  var ths = document.querySelectorAll('#amzCustTable thead th');
  var sortKeys = ['', 'c', 'n', 'p', 'd', 't', 'f'];
  for (var i = 0; i < ths.length; i++) {
    ths[i].classList.remove('sort-asc', 'sort-desc');
    if (sortKeys[i] === st.sortKey) {
      ths[i].classList.add(st.sortDir === 'asc' ? 'sort-asc' : 'sort-desc');
    }
  }

  var tbody = document.getElementById('amzCustTbody');
  if (!tbody) return;
  var html = '';
  if (pageRows.length === 0) {
    html = '<tr><td colspan="7" style="text-align:center;padding:30px;color:#94a3b8">ไม่พบข้อมูล</td></tr>';
  } else {
    for (var i = 0; i < pageRows.length; i++) {
      var r = pageRows[i];
      var idx = start + i + 1;
      var flag = st.tableType === 'new' ? r.nf : r.lf;
      var badgeClass = st.tableType === 'new' ? 'amz-cust-badge-new' : 'amz-cust-badge-lost';
      html += '<tr>' +
        '<td>' + idx + '</td>' +
        '<td>' + r.c + '</td>' +
        '<td>' + r.n + '</td>' +
        '<td>' + r.p + '</td>' +
        '<td>' + r.d + '</td>' +
        '<td class="td-right">' + _amzCustFmtBaht(r.t) + '</td>' +
        '<td><span class="' + badgeClass + '">' + flag + '</span></td>' +
        '</tr>';
    }
  }
  tbody.innerHTML = html;

  // count
  var countEl = document.getElementById('amzCustCount');
  if (countEl) countEl.textContent = 'แสดง ' + (total > 0 ? (start+1) : 0) + '-' + end + ' จาก ' + _amzCustFmt(total) + ' รายการ';

  // pagination
  var pgEl = document.getElementById('amzCustPagination');
  if (!pgEl) return;
  if (pages <= 1) { pgEl.innerHTML = ''; return; }
  var pgHtml = '<div>';
  pgHtml += '<button ' + (st.page <= 1 ? 'disabled' : 'onclick="amzCustSetPage(' + (st.page-1) + ')"') + '>&laquo; ก่อนหน้า</button> ';

  var pStart = Math.max(1, st.page - 2);
  var pEnd = Math.min(pages, st.page + 2);
  if (pStart > 1) pgHtml += '<button onclick="amzCustSetPage(1)">1</button> ';
  if (pStart > 2) pgHtml += '<span style="padding:0 4px">...</span> ';
  for (var p = pStart; p <= pEnd; p++) {
    if (p === st.page) pgHtml += '<button class="pg-current">' + p + '</button> ';
    else pgHtml += '<button onclick="amzCustSetPage(' + p + ')">' + p + '</button> ';
  }
  if (pEnd < pages - 1) pgHtml += '<span style="padding:0 4px">...</span> ';
  if (pEnd < pages) pgHtml += '<button onclick="amzCustSetPage(' + pages + ')">' + pages + '</button> ';
  pgHtml += '<button ' + (st.page >= pages ? 'disabled' : 'onclick="amzCustSetPage(' + (st.page+1) + ')"') + '>ถัดไป &raquo;</button>';
  pgHtml += '</div>';
  pgHtml += '<div>หน้า ' + st.page + ' / ' + pages + '</div>';
  pgEl.innerHTML = pgHtml;
}

function renderAmzCustomers() {
  _amzCustState.page = 1;
  var sel = document.getElementById('amzCustChannelSel');
  var mainCh = typeof amzGetChannel === 'function' ? amzGetChannel() : 'All';
  var subEl = document.getElementById('amzCustSubtitle');
  if (mainCh === 'Amazon') {
    _amzCustState.channel = 'amazon';
    if (sel) { sel.value = 'amazon'; sel.style.display = 'none'; }
    if (subEl) subEl.textContent = 'วิเคราะห์การเปลี่ยนแปลงฐานลูกค้า Amazon';
  } else if (mainCh === 'Souvenir') {
    _amzCustState.channel = 'souvenir';
    if (sel) { sel.value = 'souvenir'; sel.style.display = 'none'; }
    if (subEl) subEl.textContent = 'วิเคราะห์การเปลี่ยนแปลงฐานลูกค้า ร้านขายของฝาก';
  } else {
    if (sel) { sel.style.display = ''; sel.value = 'all'; _amzCustState.channel = 'all'; }
    if (subEl) subEl.textContent = 'วิเคราะห์การเปลี่ยนแปลงฐานลูกค้า Amazon & ร้านขายของฝาก';
  }

  _amzCustRenderKPI();
  _amzCustRenderChart();
  _amzCustRenderPills();
  _amzCustPopulateProvinces();
  _amzCustRenderTable();
}
